records["UI/help.lua"]={bytes=27652,hash=4079399504,oldBytes=27318,oldHash=1142123770,changes={{at=2790,current="-- Some bound controls are Lua wrappers (editor objects), not frames; the\n-- tooltip's owner APIs reject those with \"Wrong object type\".\nlocal function tooltipOwned(control)\n    if not GameTooltip then return false end\n    local ok,owned=pcall(GameTooltip.IsOwned,GameTooltip,control)\n    return ok and owned\nend\n\n",previous=""},{at=3767,current="        if tooltipOwned(control) then if descriptor.brief~=control.tooltip then GameTooltip:AddLine(descriptor.brief,1,1,1,true) end\n        else\n            if not pcall(GameTooltip.SetOwner,GameTooltip,control,'ANCHOR_RIGHT') then return end\n            GameTooltip:SetText(descriptor.brief,1,1,1,1,true)\n        end\n",previous="        if GameTooltip:IsOwned(control) then if descriptor.brief~=control.tooltip then GameTooltip:AddLine(descriptor.brief,1,1,1,true) end\n        else GameTooltip:SetOwner(control,'ANCHOR_RIGHT');GameTooltip:SetText(descriptor.brief,1,1,1,1,true) end\n"},{at=4231,current="        if current() and tooltipOwned(control) then GameTooltip:Hide() end\n",previous="        if current() and GameTooltip and GameTooltip:IsOwned(control) then GameTooltip:Hide() end\n"},{at=4833,current="        if tooltipOwned(control) then GameTooltip:Hide() end\n",previous="        if GameTooltip and GameTooltip:IsOwned(control) then GameTooltip:Hide() end\n"}}}
