records["UI/settings_conditions.lua"]={bytes=21503,hash=1658663113,oldBytes=20771,oldHash=2993379710,changes={{at=141,current="-- Hidden, Switch Condition and Announcement Condition share one row in\n-- thirds; a row too narrow for their captions wraps instead of clipping.\nfunction addon:LayoutConditionFlags(hidden,switch,announcement,y,width)\n    local widest=0;for _,check in ipairs({hidden,switch,announcement}) do widest=math.max(widest,check:GetFontString():GetStringWidth()) end\n    local height=self:LayoutWorkbenchRow({hidden,switch,announcement},0,y,width,{minimum=widest+30,text=22})\n    hidden.rmFlagRowsHeight=height;return height\nend\n",previous=""},{at=8105,current="        local special=(self.conditionSpecials or {})[tag]~=nil;local flagsY=p.y\n",previous="        local special=(self.conditionSpecials or {})[tag]~=nil\n"},{at=9233,current="        -- The three flags share their row in thirds and wrap rather than clip.\n        self:LayoutConditionFlags(hidden,switch,announcement,flagsY,p.width);p.y=flagsY+hidden.rmFlagRowsHeight+2\n",previous=""}}}
records["UI/settings_form.lua"]={bytes=38390,hash=2082903889,oldBytes=35570,oldHash=1062779351,changes={{at=492,current="    local p={frame=addon:TrackWorkbenchSize(CreateFrame('Frame',nil,parent)),pool={},counts={},fields={},edits={},cleanups={},active=false,generation=0,isSettingsForm=true}\n",previous="    local p={frame=CreateFrame('Frame',nil,parent),pool={},counts={},fields={},edits={},cleanups={},active=false,generation=0,isSettingsForm=true}\n"},{at=3353,current="        local c=self.pool[kind][i];if not c then c=build();addon:TrackWorkbenchRegion(c);self.pool[kind][i]=c end;if c.SetParent then c:SetParent(self.surface or self.child) end;c:Show();return c\n",previous="        local c=self.pool[kind][i];if not c then c=build();self.pool[kind][i]=c end;if c.SetParent then c:SetParent(self.surface or self.child) end;c:Show();return c\n"},{at=6676,current="            c.tooltip=entry.text;if icon then c.icon:SetTexture(addon:ControlTexture(icon));c:SetText('');c:SetWidth(20) else c:SetText(entry.text);c:SetWidth(math.min(110,self.width)) end\n            -- A row that no longer fits wraps instead of running past the pane.\n            if x>0 and x+c:GetWidth()>self.width then x=0;y=y+28;self.y=self.y+28 end\n            c:ClearAllPoints();c:SetPoint('TOPLEFT',x,-y);x=x+c:GetWidth()+4\n",previous="            c:ClearAllPoints();c:SetPoint('TOPLEFT',x,-y);c.tooltip=entry.text;if icon then c.icon:SetTexture(addon:ControlTexture(icon));c:SetText('');c:SetWidth(20) else c:SetText(entry.text);c:SetWidth(110) end;x=x+c:GetWidth()+4\n"},{at=27947,current="        local promptWidth=addon:FitWorkbenchPrompt(prompt.frame,self.frame,430);prompt.text:SetWidth(math.max(1,promptWidth-24))\n",previous=""},{at=29533,current="        -- The four channels share the row beside the swatch in two columns.\n        local channelWidth=math.max(40,(self.width-278-4)/2)\n",previous=""},{at=29725,current="            local c=self:Acquire('colorInputs',function() return addon:CreateWorkbenchEditBox(self.child) end);c:ClearAllPoints();c:SetPoint('TOPLEFT',278+((i-1)%2)*(channelWidth+4),-y-math.floor((i-1)/2)*26);c:SetSize(channelWidth,24);c:SetText(string.format('%.3f',values[channel]));c:SetTextColor(1,1,1);c:EnableMouse(true);c:ClearFocus();c:SetTextInsets(16,3,0,0)\n",previous="            local c=self:Acquire('colorInputs',function() return addon:CreateWorkbenchEditBox(self.child) end);c:ClearAllPoints();c:SetPoint('TOPLEFT',278+((i-1)%2)*84,-y-math.floor((i-1)/2)*26);c:SetSize(80,24);c:SetText(string.format('%.3f',values[channel]));c:SetTextColor(1,1,1);c:EnableMouse(true);c:ClearFocus();c:SetTextInsets(16,3,0,0)\n"},{at=32332,current="    -- Every cleanup runs even if one fails; a failure part-way used to leave\n    -- the old page's controls on screen and the page unusable.\n    function p:RunCleanups()\n        local cleanups=self.cleanups;self.cleanups={}\n        for _,cleanup in ipairs(cleanups) do\n            local ok,why=pcall(cleanup)\n            if not ok then local handler=geterrorhandler and geterrorhandler();if handler then pcall(handler,why) end end\n        end\n    end\n",previous=""},{at=33066,current="        self:RunCleanups()\n",previous="        for _,cleanup in ipairs(self.cleanups) do cleanup() end;self.cleanups={}\n"},{at=33191,current="        self.creationUsed=false;self.creationUsedForNew=false;self.counts={};self.fields={};self.edits={};if self.ResetLayout then self:ResetLayout() end;self.y=4;self.width=math.max(340,self.frame:GetWidth()-40);self.child:SetWidth(self.width)\n",previous="        self.creationUsed=false;self.creationUsedForNew=false;self.counts={};self.fields={};self.edits={};if self.ResetLayout then self:ResetLayout() end;self.y=4;self.width=math.max(340,math.min(760,self.frame:GetWidth()-40));self.child:SetWidth(self.width)\n"},{at=34680,current="        addon:ReserveWorkbenchHelpCorner(self.frame,self.scroll,8)\n",previous=""},{at=34980,current="    -- Geometry alone changed: draw again at the new width, carrying every\n    -- pending input across as typed (invalid text included) without\n    -- committing it, so a resize never loses or silently applies an edit.\n    function p:Relayout()\n        if not self.active then return end\n        for _,record in ipairs(self.edits) do\n            if record.control.HasFocus and record.control:HasFocus() then\n                -- Typing keeps its control, text and caret; draw again once\n                -- the input lets go. A newer drawing supersedes this wait.\n                self.relayoutWaiter=self.relayoutWaiter or CreateFrame('Frame',nil,self.frame)\n                local token=self.generation\n                addon:SetUIScript(self.relayoutWaiter,'OnUpdate',function(waiter)\n                    if not self.active or self.generation~=token then addon:SetUIScript(waiter,'OnUpdate',nil);return end\n                    for _,current in ipairs(self.edits) do if current.control.HasFocus and current.control:HasFocus() then return end end\n                    addon:SetUIScript(waiter,'OnUpdate',nil);self:Relayout()\n                end)\n                return\n            end\n        end\n        local pending={}\n        for _,record in ipairs(self.edits) do if record.dirty then for key,control in pairs(self.fields) do if control==record.control then pending[key]=control:GetText() end end end end\n        self:Draw()\n        for key,text in pairs(pending) do\n            local control=self.fields[key]\n            for _,record in ipairs(self.edits) do if control and record.control==control then\n                control:SetText(text);record.dirty=true\n                local valid=record.parse(text)~=nil;control:SetTextColor(1,valid and 1 or .35,valid and 1 or .35)\n                if self.transactionKeys and self.fields.apply then self.fields.apply:Enable() end\n            end end\n        end\n    end\n    function p:SetWidth(n) local changed=n~=self.frame:GetWidth();self.frame:SetWidth(n);self:Layout();if changed then self:Relayout() end end\n",previous="    function p:SetWidth(n) local changed=n~=self.frame:GetWidth();self.frame:SetWidth(n);self:Layout();if changed and self.active and self:FlushEdits() then self:Draw() end end\n"},{at=37562,current="        self:RunCleanups()\n",previous="        for _,cleanup in ipairs(self.cleanups) do cleanup() end;self.cleanups={}\n"}}}
records["UI/settings_general.lua"]={bytes=20131,hash=1238136492,oldBytes=17307,oldHash=680690495,changes={{at=473,current="    local enableY=p.y\n",previous=""},{at=670,current="    p:Check('disable_buttons',L['Disable Bar Highlighting'],profile.disable_buttons,function(v) profile.disable_buttons=v;p:RunSettingsEffect('buttons',function() if v then self:GlowClear() end end) end)\n    -- Enable and Disable Bar Highlighting share their row half and half.\n    self:LayoutWorkbenchRow({p.fields.enable,p.fields.disable_buttons},0,enableY,p.width,{text=22});p.y=enableY+30\n",previous=""},{at=1299,current="    p:Slider('idle_poll',L['Idle Re-check Interval (seconds)'],profile.idle_poll or 1,0,5,.25,function(v) profile.idle_poll=v end)\n    p:Slider('autoswitch_poll',L['Auto-Switch Re-check Interval (seconds)'],profile.autoswitch_poll or 1,0,10,.25,function(v) profile.autoswitch_poll=v;profile.disable_autoswitch=nil;p:RunSettingsEffect('autoswitch_poll',function() self:StartAutoSwitchTimer() end) end)\n",previous="    p:Check('disable_autoswitch',L['Disable Auto-Switching'],profile.disable_autoswitch,function(v) profile.disable_autoswitch=v end)\n    local checkY=p.y-30\n    local bar=p:Check('disable_buttons',L['Disable Bar Highlighting'],profile.disable_buttons,function(v) profile.disable_buttons=v;p:RunSettingsEffect('buttons',function() if v then self:GlowClear() end end) end)\n    local half=(p.width-8)/2;p.fields.disable_autoswitch:SetWidth(half);p.fields.disable_autoswitch:GetFontString():SetWidth(half-22);bar:ClearAllPoints();bar:SetPoint('TOPLEFT',half+8,-checkY);bar:SetWidth(half);bar:GetFontString():SetWidth(half-22);p.y=p.y-30\n"},{at=13215,current="    -- Diagnostics: one column per capture kind, its capture button above its\n    -- report button. While a capture runs its button stops it (the report is\n    -- kept); a report button stays disabled until that kind has a report.\n    -- Labels follow live state, whoever started or ended the capture, but only\n    -- while this page is shown. Each action uses live settings, never a draft.\n    local captures={}\n    local function call(method,...) local fn=self[method];if type(fn)~='function' then return false end;local ok,value=pcall(fn,self,...);return ok and value end\n    local function stopper(kind,method) return function()\n        if type(self.HandlePerformanceCommand)=='function' then return self:HandlePerformanceCommand(kind..' stop') end\n        local ok=call(method);return ok,''\n    end end\n    local function stored(method) return function() local fn=self[method];if type(fn)~='function' then return false end;local ok,value=pcall(fn,self);return ok and type(value)=='string' end end\n",previous=""},{at=14254,current="        captures[#captures+1]={key='cpu_capture',reportKey='cpu_report',start=L['Capture CPU (10s)'],stop=L['Stop CPU capture'],report=L['CPU report'],\n            running=function() return call('IsCPUProfileRunning')==true end,hasReport=stored('GetCPUProfileReport'),\n            begin=function() return self:RunCPUProfileAction('start') end,finish=stopper('cpu','StopCPUProfile'),open=function() return self:RunCPUProfileAction('report') end}\n",previous="        local controls={\n            {key='cpu_capture',text=L['Capture CPU (10s)'],action='start'},\n            {key='cpu_report',text=L['CPU report'],action='report'},\n            {key='cpu_cancel',text=L['Cancel capture'],action='cancel'},\n            {key='cpu_probe',text=L['Native profiler probe'],action='probe'},\n        }\n"},{at=14761,current="            captures[#captures+1]={key='cpu_runtime_capture',reportKey='cpu_runtime_report',start=L['Capture runtime (10s)'],stop=L['Stop runtime capture'],report=L['Runtime report'],\n                running=function() return call('IsCPURuntimeCaptureRunning')==true end,hasReport=stored('GetCPURuntimeCaptureReport'),\n                begin=function() return self:RunCPUProfileAction('runtime') end,finish=stopper('runtime','StopCPURuntimeCapture'),open=function() return self:RunCPUProfileAction('runtimereport') end}\n",previous="            controls[#controls+1]={key='cpu_runtime_capture',text=L['Capture runtime (10s)'],action='runtime'}\n            controls[#controls+1]={key='cpu_runtime_report',text=L['Runtime report'],action='runtimereport'}\n"},{at=15350,current="            captures[#captures+1]={key='memory_capture',reportKey='memory_report',start=L['Capture memory (10m)'],stop=L['Stop memory capture'],report=L['Memory report'],\n                running=function() return call('IsMemoryCaptureRunning')==true end,hasReport=stored('GetMemoryCaptureReport'),\n                begin=function() return self:RunCPUProfileAction('memory') end,finish=stopper('memory','CompleteMemoryCapture'),open=function() return self:RunCPUProfileAction('memoryreport') end}\n",previous="            controls[#controls+1]={key='memory_capture',text=L['Capture memory (10m)'],action='memory'}\n            controls[#controls+1]={key='memory_report',text=L['Memory report'],action='memoryreport'}\n            controls[#controls+1]={key='memory_stop',text=L['Stop memory capture'],action='memorystop'}\n"},{at=15857,current="    end\n    if self.RunCastCaptureAction then\n        -- The cast report copies its snapshot, so it is checked only when the\n        -- running state changes (and now and then as a safety net).\n        captures[#captures+1]={key='cast_capture',reportKey='cast_report',start=L['Capture casts (30s)'],stop=L['Stop cast capture'],report=L['Cast report'],costly=true,\n            running=function() return type(self.GetCastCaptureState)=='function' and self:GetCastCaptureState()==true end,\n            hasReport=function() if type(self.GetCastCaptureState)~='function' then return true end;local _,available=self:GetCastCaptureState(true);return available==true end,\n            begin=function() return self:RunCastCaptureAction('start') end,finish=function() return self:RunCastCaptureAction('stop') end,open=function() return self:RunCastCaptureAction('report') end}\n    end\n    if #captures>0 then\n        local token=p.generation;local minimumWidth=120;local diagnosticY=p.y\n        local function paint(entry,force)\n            local running=entry.running()\n            local has=entry.has\n            if not running and (force or not entry.costly or running~=entry.wasRunning or (entry.age or 0)>=2) then has=entry.hasReport()==true;entry.age=0 end\n            if running then has=false end\n            entry.wasRunning=running;entry.has=has\n            entry.button:SetText(running and entry.stop or entry.start)\n            if has then entry.reportButton:Enable() else entry.reportButton:Disable() end\n        end\n        local function repaint(force) if p:Valid(token) then for _,entry in ipairs(captures) do paint(entry,force) end end end\n        for _,entry in ipairs(captures) do\n            local button=p:Button(entry.key,entry.start,function() end);local reportButton=p:Button(entry.reportKey,entry.report,function() end)\n            entry.button,entry.reportButton=button,reportButton\n            for _,text in ipairs({entry.start,entry.stop}) do button:SetText(text);minimumWidth=math.max(minimumWidth,button:GetFontString():GetStringWidth()+20) end\n            self:SetUIScript(button,'OnClick',p:Guard(function()\n                local action=entry.running() and entry.finish or entry.begin\n                local ok,message,current=action()\n                if current==false or not p:Valid(token) then return end\n                if message and message~='' then p:Message(message,ok) end;repaint(true)\n            end))\n            self:SetUIScript(reportButton,'OnClick',p:Guard(function()\n                local ok,message,current=entry.open()\n                if current==false or not p:Valid(token) then return end\n                p:Message(message or '',ok);repaint(true)\n",previous="        local diagnosticY=p.y;local buttons={};local minimumWidth=120\n        local diagnosticToken=p.generation\n        for i,entry in ipairs(controls) do\n            local control=p:Button(entry.key,entry.text,function() end)\n            buttons[i]=control\n            minimumWidth=math.max(minimumWidth,control:GetFontString():GetStringWidth()+20)\n            -- Diagnostics use live runtime settings, without applying/flushing a draft.\n            self:SetUIScript(control,'OnClick',p:Guard(function()\n                local ok,message=self:RunCPUProfileAction(entry.action)\n                if not p:Valid(diagnosticToken) then return end\n                p:Message(message,ok)\n"},{at=18576,current="        local gap=4\n        local columns=math.max(1,math.min(#captures,math.floor((p.width+gap)/(minimumWidth+gap))))\n        local each=(p.width-(columns-1)*gap)/columns\n        for i,entry in ipairs(captures) do\n            local x=((i-1)%columns)*(each+gap);local top=diagnosticY+math.floor((i-1)/columns)*58\n            entry.button:ClearAllPoints();entry.button:SetPoint('TOPLEFT',x,-top);entry.button:SetWidth(each)\n            entry.reportButton:ClearAllPoints();entry.reportButton:SetPoint('TOPLEFT',x,-top-28);entry.reportButton:SetWidth(each)\n",previous="        local columns=p.width>=minimumWidth*4+12 and 4 or p.width>=minimumWidth*2+4 and 2 or 1\n        local controlWidth=(p.width-(columns-1)*4)/columns\n        for i,control in ipairs(buttons) do\n            control:ClearAllPoints();control:SetPoint('TOPLEFT',((i-1)%columns)*(controlWidth+4),-diagnosticY-math.floor((i-1)/columns)*28);control:SetWidth(controlWidth)\n"},{at=19142,current="        p.y=diagnosticY+math.ceil(#captures/columns)*58\n        repaint(true)\n        local watcher=p:Acquire('captureWatcher',function() return CreateFrame('Frame',nil,p.child) end);local elapsed=0\n        self:SetUIScript(watcher,'OnUpdate',function(frame,delta)\n            if not p:Valid(token) then self:SetUIScript(frame,'OnUpdate',nil);return end\n            elapsed=elapsed+(delta or 0);if elapsed<